import pytest
import cart

# Helper functions for parameterized tests
def expect_apply_discount(price, percent, expected):
    assert cart.apply_discount(price, percent) == expected

@pytest.mark.parametrize(
    "price,percent,expected",
    [
        (200, 15, 170.0),   # basic example
        (100, 0, 100.0),    # no discount
        (50, 100, 0.0),     # full discount
        (123.45, 10, 111.105),  # rounding to two decimals
    ],
)
def test_apply_discount(price, percent, expected):
    # apply_discount rounds to 2 decimals
    result = cart.apply_discount(price, percent)
    assert isinstance(result, float)
    assert round(result, 2) == round(expected, 2)

# Test invalid arguments for apply_discount
@pytest.mark.parametrize("price", [ -1, -10.5])
def test_apply_discount_negative_price(price):
    with pytest.raises(ValueError):
        cart.apply_discount(price, 20)

@pytest.mark.parametrize("percent", [-5, 101])
def test_apply_discount_invalid_percent(percent):
    with pytest.raises(ValueError):
        cart.apply_discount(100, percent)

# bulk_discount_percent tests
@pytest.mark.parametrize(
    "quantity,expected",
    [
        (99, 0),     # below threshold
        (10, 5),
        (50, 10),
        (100, 15),
        (150, 15),
    ],
)
def test_bulk_discount_percent(quantity, expected):
    assert cart.bulk_discount_percent(quantity) == expected

@pytest.mark.parametrize("quantity", [0, -5, 3.2])
def test_bulk_discount_invalid_quantity(quantity):
    with pytest.raises(ValueError):
        cart.bulk_discount_percent(quantity)

# parse_coupon tests
valid_cases = {
    "SAVE10": 10,
    "save20": 20,
    " SAVE30 ": 30,
}
for code, percent in valid_cases.items():
    def make_test(code=code, percent=percent):
        assert cart.parse_coupon(code) == percent
    # create a test function for each case
    globals()[f"test_parse_coupon_{code.strip().replace(' ', '_').lower()}"] = make_test

@pytest.mark.parametrize("invalid", ["SAV10", "SAVE0", "SAVE51", "ABC10", ""]) 
 def test_parse_coupon_invalid(invalid):
    with pytest.raises(ValueError):
        cart.parse_coupon(invalid)

# shipping_fee tests
@pytest.mark.parametrize(
    "subtotal,member,expected",
    [
        (0, False, 60),
        (500, True, 30),
        (999.99, False, 60),
        (1000, False, 0),
        (2000, True, 0),
    ],
)
def test_shipping_fee(subtotal, member, expected):
    assert cart.shipping_fee(subtotal, member) == expected

@pytest.mark.parametrize("subtotal", [-1, -10.5])
def test_shipping_fee_negative(subtotal):
    with pytest.raises(ValueError):
        cart.shipping_fee(subtotal)

# Cart class tests
class TestCart:
    def setup_method(self):
        self.cart = cart.Cart()

    def test_empty_cart_totals(self):
        assert self.cart.items() == {}
        assert self.cart.subtotal() == 0.0
        # total with no coupon or membership should equal shipping of 60
        assert self.cart.total() == 60.0

    def test_add_and_remove_items(self):
        self.cart.add_item("apple", 100, 2)
        self.cart.add_item("banana", 50, 3)
        # adding more apples should increase quantity
        self.cart.add_item("apple", 100, 1)
        assert self.cart.items() == {"apple": (100, 3), "banana": (50, 3)}
        assert self.cart.subtotal() == 100*3 + 50*3
        # remove some bananas
        self.cart.remove_item("banana", 2)
        assert self.cart.items()["banana"] == (50, 1)
        # remove remaining banana should delete key
        self.cart.remove_item("banana")
        assert "banana" not in self.cart.items()

    def test_add_same_item_different_price(self):
        self.cart.add_item("pear", 80)
        with pytest.raises(ValueError):
            self.cart.add_item("pear", 90)

    @pytest.mark.parametrize(
        "price,quantity",
        [(10, -1), (-5, 3), (20, 0)],
    )
    def test_add_invalid(self, price, quantity):
        with pytest.raises(ValueError):
            self.cart.add_item("invalid", price, quantity)

    @pytest.mark.parametrize(
        "name,quantity",
        [("nonexistent", 1), ("apple", -3)],
    )
    def test_remove_invalid(self, name, quantity):
        with pytest.raises(ValueError):
            self.cart.remove_item(name, quantity)

    def test_total_with_coupon_and_membership(self):
        # add items to subtotal 1500 (free shipping)
        self.cart.add_item("widget", 500, 3)  # subtotal 1500
        # coupon SAVE10 -> 10% discount on total before shipping
        assert self.cart.total(member=True, coupon="SAVE10") == 1350.0

    def test_total_no_coupon_member(self):
        self.cart.add_item("item", 100, 5)  # subtotal 500
        # member pays half shipping 30 -> total 530
        assert self.cart.total(member=True) == 530.0

